#include <stdio.h>
#include <stdlib.h>

struct S {
    int x, y;
} s[4];

int solve(int n) {
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (s[i].x != s[j].x && s[i].y != s[j].y) {
                return abs((s[i].x - s[j].x) * (s[i].y - s[j].y));
            }
        }
    }
    return -1;
}

int main() {
    int n;
    while (scanf("%d", &n) == 1) {
        for (int i = 0; i < n; ++i) {
            scanf("%d%d", &s[i].x, &s[i].y);
        }
        printf("%d\n", solve(n));
    }
    return 0;
}

